import tkinter as tkimport shutil"""Faire un exe:pip install pyinstallerpyinstaller --onefile --noconsole diskspace.py"""REFRESH_MS = 5000RIGHT_MARGIN = 270TOP_MARGIN = -4def get_free_space(drive):    try:        free = shutil.disk_usage(drive).free        return free / (1024 ** 3)    except Exception:        return Nonedef update():    c = get_free_space("C:\\")    d = get_free_space("D:\\")    parts = []    if c is not None:        parts.append(f"C: {c:.1f} Go")    else:        parts.append("C: ?")    if d is not None:        parts.append(f"D: {d:.1f} Go")    else:        parts.append("D: ?")    label.config(text="    ".join(parts))    root.after(REFRESH_MS, update)# ---------------------------------------------------------# Fenêtre# ---------------------------------------------------------root = tk.Tk()root.overrideredirect(True)       # pas de bordure / barre de titreroot.attributes("-topmost", True) # toujours au-dessusroot.attributes("-alpha", 0.80)   # transparenceroot.configure(bg="black")# bord arrondi"""root.update_idletasks()hwnd = root.winfo_id()import ctypesfrom ctypes import wintypesDWMWA_WINDOW_CORNER_PREFERENCE = 33DWMWCP_ROUND = 2ctypes.windll.dwmapi.DwmSetWindowAttribute(    hwnd,    DWMWA_WINDOW_CORNER_PREFERENCE,    ctypes.byref(wintypes.DWORD(DWMWCP_ROUND)),    ctypes.sizeof(wintypes.DWORD))"""# bord arrondi - enddef make_rounded_0(hwnd, width, height, radius=10   ):    import ctypes    HRGN = ctypes.windll.gdi32.CreateRoundRectRgn(        0, 0,        width + 1, height + 1,        radius, radius    )    ctypes.windll.user32.SetWindowRgn(        hwnd,        HRGN,        True    )    def make_rounded(hwnd, width, height, radius=10):    import ctypes    user32 = ctypes.windll.user32    gdi32 = ctypes.windll.gdi32    # Région rectangulaire avec coins arrondis    region = gdi32.CreateRoundRectRgn(        0, 0,        width, height,        radius * 2,        radius * 2    )    # Applique la région à la fenêtre    user32.SetWindowRgn(hwnd, region, True)label = tk.Label(    root,    text="",    font=("Segoe UI", 8),    fg="white",    bg="gray",    padx=2,    pady=1)label.pack()# Force le calcul de la taille de la fenêtreroot.update_idletasks()# Position haut-droitescreen_width = root.winfo_screenwidth()window_width = root.winfo_width()x = screen_width - window_width - RIGHT_MARGINy = TOP_MARGINroot.geometry(f"+{x}+{y}")# arrondi v2"""root.update_idletasks()make_rounded(    root.winfo_id(),    root.winfo_width(),    root.winfo_height(),    10)"""update()root.mainloop()